     fn rc4_encrypt(data: &[u8], key: &[u8]) -> Vec<u8> {
         let mut s = (0..256).collect::<Vec<u8>>();
         let mut j = 0;
         for i in 0..256 {
             j = (j + s[i] as usize + key[i % key.len()] as usize) % 256;
             s.swap(i, j);
         }
         let mut output = Vec::new();
         let mut i = 0;
         let mut j = 0;
         for &byte in data {
             i = (i + 1) % 256;
             j = (j + s[i] as usize) % 256;
             s.swap(i, j);
             let k = s[(s[i] + s[j]) as usize % 256];
             output.push(byte ^ k);
         }
         output
     }
