# pingpull_c2_extractor.py (Ghidra Python)
def extract_c2_domains(currentProgram):
    c2_domains = set()
    refs = currentProgram.getReferencesTo(currentProgram.getMemory().getBlock(".rdata"))
    for ref in refs:
        addr = ref.getFromAddress()
        string = getDataAt(addr)
        if string and string.getValue():
            domain = string.getValue().lower()
            if "c2" in domain or ".com" in domain:
                c2_domains.add(domain)
    print(f"[+] Extracted C2 Domains: {c2_domains}")
    return c2_domains

